/* Jauge de niveau d'infestation — élément signature (hero + kits insectes) */
function InfestationGauge({ compact = false }) {
  const seg = "flex-1 flex items-center justify-center text-[10px] tracking-widest uppercase";
  return (
    <div className={compact ? "w-full max-w-xs" : "w-full max-w-md"}>
      <div className="flex h-6 rounded-sm overflow-hidden border" style={{ borderColor: COLORS.ink }}>
        <div className={seg} style={{ background: COLORS.green, color: COLORS.paper }}>Légère</div>
        <div className={seg} style={{ background: COLORS.amber, color: COLORS.ink }}>Modérée</div>
        <div
          className={seg}
          style={{
            color: COLORS.paper,
            background: `repeating-linear-gradient(45deg, ${COLORS.rust}, ${COLORS.rust} 4px, #8a2f20 4px, #8a2f20 8px)`,
          }}
        >
          Forte
        </div>
      </div>
      {!compact && (
        <p className="f-mono text-[10px] mt-1.5" style={{ color: COLORS.ink, opacity: 0.65 }}>
          NUISIKIT traite les infestations légères, modérées et fortes avec un mode d'emploi détaillé pour vous accompagner étape par étape.
        </p>
      )}
    </div>
  );
}

