const ALL_PRODUCTS = [...PRODUITS_PUNAISES, ...PRODUITS_CAFARDS, ...PRODUITS_FOURMIS, ...PRODUITS_RONGEURS, ...AEROSOLS, EQUIPEMENT_PROTECTION, PULVERISATEUR];

const TRAITEMENT_COMPLEMENTAIRE = [...PRODUITS_PUNAISES, ...PRODUITS_CAFARDS, ...PRODUITS_FOURMIS, ...PRODUITS_RONGEURS, ...AEROSOLS.filter((a) => ["aerosol-repulsif-rongeurs", "aerosol-guepes-frelons"].includes(a.id))].filter(
  (p, i, arr) => arr.findIndex((q) => q.id === p.id) === i
);

function findProductById(id) {
  return ALL_PRODUCTS.find((p) => p.id === id);
}

/* ---------------------------------------------------------
   Fiche produit individuelle
--------------------------------------------------------- */
function ProductCard({ produit, onAdd, onOpenDetails }) {
  const [qty, setQty] = useState(1);
  return (
    <div className="flex flex-col justify-between p-5 border" style={{ borderColor: COLORS.line, background: COLORS.paper }}>
      <button onClick={() => onOpenDetails(produit)} className="text-left w-full" aria-label={`Voir la fiche ${produit.nom}`}>
        {produit.image && (
          <div className="w-full h-36 mb-3 flex items-center justify-center overflow-hidden" style={{ background: COLORS.paperDim, border: `1px solid ${COLORS.line}` }}>
            <img src={produit.image} alt={produit.nom} className="max-h-full max-w-full object-contain" />
          </div>
        )}
        <p className="f-mono text-[11px] tracking-wider" style={{ color: COLORS.amberDark }}>{produit.spec.toUpperCase()}</p>
        <h3 className="f-display text-lg mt-1 hover:underline" style={{ color: COLORS.ink }}>{produit.nom}</h3>
        <p className="f-body text-sm mt-2 leading-snug" style={{ color: COLORS.ink, opacity: 0.75 }}>{produit.role}</p>
      </button>
      <div className="mt-5 flex items-end justify-between">
        <span className="f-mono text-base font-semibold" style={{ color: COLORS.ink }}>{eur(produit.prix)}</span>
        <div className="flex items-center gap-2">
          <div className="flex items-center border" style={{ borderColor: COLORS.ink }}>
            <button aria-label="Diminuer la quantité" onClick={() => setQty((q) => Math.max(1, q - 1))} className="p-1.5 hover:opacity-70">
              <Minus size={13} color={COLORS.ink} />
            </button>
            <span className="f-mono text-sm w-6 text-center" style={{ color: COLORS.ink }}>{qty}</span>
            <button aria-label="Augmenter la quantité" onClick={() => setQty((q) => q + 1)} className="p-1.5 hover:opacity-70">
              <Plus size={13} color={COLORS.ink} />
            </button>
          </div>
          <button onClick={() => onAdd(produit, qty)} className="f-body text-sm font-semibold px-3 py-2 transition-opacity hover:opacity-85" style={{ background: COLORS.ink, color: COLORS.paper }}>
            Ajouter
          </button>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Formule groupée mise en avant (une par catégorie : punaises, cafards, fourmis)
--------------------------------------------------------- */
function FeaturedBundle({ title, description, composition, sumPrice, prix, cartItem, addToCart, showGauge, image, linkedProducts, onOpenDetails }) {
  return (
    <>
      <div className="flex items-end justify-between flex-wrap gap-4 mb-8">
        <div>
          <p className="f-mono text-xs tracking-[0.2em] uppercase mb-2" style={{ color: COLORS.amberDark }}>Formule groupée</p>
          <h2 className="f-display text-3xl sm:text-4xl" style={{ color: COLORS.ink }}>{title}</h2>
        </div>
        {showGauge && <InfestationGauge compact />}
      </div>

      <div className="flex flex-col lg:flex-row gap-8 lg:gap-0 border" style={{ borderColor: COLORS.ink, background: COLORS.paper }}>
        <div className="flex-1 p-6 sm:p-8 border-b lg:border-b-0 lg:border-r" style={{ borderColor: COLORS.line }}>
          {image && (
            <div className="w-full h-40 sm:h-44 mb-6 flex items-center justify-center overflow-hidden" style={{ background: COLORS.paperDim, border: `1px solid ${COLORS.line}` }}>
              <img src={image} alt={title} className="max-h-full max-w-full object-contain" />
            </div>
          )}
          {description && (
            <p className="f-body text-sm mb-5" style={{ color: COLORS.ink, opacity: 0.75 }}>{description}</p>
          )}
          <ul className="space-y-2.5">
            {composition.map((item) => {
              const linked = linkedProducts && linkedProducts[item];
              return (
                <li key={item} className="flex items-start gap-3 f-mono text-sm" style={{ color: COLORS.ink }}>
                  <span className="w-1.5 h-1.5 rounded-full mt-1.5 flex-shrink-0" style={{ background: COLORS.green }} />
                  {linked ? (
                    <button onClick={() => onOpenDetails(linked)} className="text-left hover:underline" style={{ color: COLORS.ink }}>
                      {item}
                    </button>
                  ) : (
                    item
                  )}
                </li>
              );
            })}
          </ul>
        </div>

        <div className="lg:w-72 p-6 sm:p-8 flex flex-col justify-between" style={{ background: COLORS.ink }}>
          <div>
            <p className="f-mono text-xs" style={{ color: COLORS.paper, opacity: 0.55 }}>Prix à l'unité cumulé</p>
            <p className="f-mono text-sm line-through mt-1" style={{ color: COLORS.paper, opacity: 0.5 }}>{eur(sumPrice)}</p>
            <p className="f-display text-4xl mt-3" style={{ color: COLORS.amber }}>{eur(prix)}</p>
            <p className="f-mono text-[11px] mt-1" style={{ color: COLORS.paper, opacity: 0.55 }}>soit {eur(sumPrice - prix)} d'économie</p>
          </div>
          <button onClick={() => addToCart(cartItem, 1)} className="mt-8 f-body font-semibold text-sm px-5 py-3 transition-opacity hover:opacity-85" style={{ background: COLORS.amber, color: COLORS.ink }}>
            Ajouter le kit complet
          </button>
        </div>
      </div>
    </>
  );
}

