function ModeEmploiModal({ familleKey, onClose }) {
  if (!familleKey) return null;
  const data = MODE_EMPLOI[familleKey];
  if (!data) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" style={{ background: "rgba(28,35,33,0.6)" }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        className="w-full max-w-lg overflow-y-auto border"
        style={{ background: COLORS.paper, borderColor: COLORS.ink, maxHeight: "85vh", WebkitOverflowScrolling: "touch", overscrollBehavior: "contain", touchAction: "pan-y" }}
      >
        <div className="flex items-center justify-between px-6 py-4 border-b sticky top-0 z-10" style={{ borderColor: COLORS.line, background: COLORS.paper }}>
          <h2 className="f-display text-xl" style={{ color: COLORS.ink }}>{data.titre}</h2>
          <button onClick={onClose} aria-label="Fermer le mode d'emploi" className="p-1 hover:opacity-70">
            <X size={20} color={COLORS.ink} />
          </button>
        </div>

        <div className="p-6">
          {data.important && (
            <p className="f-body text-sm mb-4 px-3 py-3 border" style={{ borderColor: COLORS.ink, color: COLORS.ink, background: COLORS.paperDim }}>
              <strong>Important —</strong> {data.important}
            </p>
          )}

          {data.attention && (
            <p className="f-body text-sm mb-6 px-3 py-3 border" style={{ borderColor: COLORS.amberDark, color: COLORS.amberDark, background: COLORS.paperDim }}>
              <strong>⚠ Attention —</strong> {data.attention}
            </p>
          )}

          {data.contenu && (
            <div className="mb-6">
              <h3 className="f-display text-base mb-2" style={{ color: COLORS.ink }}>Contenu du kit</h3>
              <ul className="grid grid-cols-1 sm:grid-cols-2 gap-1">
                {data.contenu.map((c, i) => (
                  <li key={i} className="flex items-start gap-2 f-body text-sm" style={{ color: COLORS.ink, opacity: 0.85 }}>
                    <span className="w-1 h-1 rounded-full mt-2 flex-shrink-0" style={{ background: COLORS.green }} />
                    {c}
                  </li>
                ))}
              </ul>
            </div>
          )}

          <ol className="space-y-4">
            {data.etapes.map((etape, i) => {
              const titre = typeof etape === "string" ? null : etape.titre;
              const texte = typeof etape === "string" ? etape : etape.texte;
              return (
                <li key={i} className="flex gap-3">
                  <span
                    className="flex-shrink-0 w-6 h-6 rounded-full flex items-center justify-center f-mono text-xs font-semibold"
                    style={{ background: COLORS.amber, color: COLORS.ink }}
                  >
                    {i + 1}
                  </span>
                  <div>
                    {titre && <p className="f-body text-sm font-semibold mb-1" style={{ color: COLORS.ink }}>{titre}</p>}
                    <p className="f-body text-sm" style={{ color: COLORS.ink, opacity: 0.85 }}>{texte}</p>
                  </div>
                </li>
              );
            })}
          </ol>

          {data.bonnesPratiques && (
            <div className="mt-6">
              <h3 className="f-display text-base mb-2" style={{ color: COLORS.ink }}>Bonnes pratiques</h3>
              <ul className="space-y-1">
                {data.bonnesPratiques.map((b, i) => (
                  <li key={i} className="flex items-start gap-2 f-body text-sm" style={{ color: COLORS.ink, opacity: 0.85 }}>
                    <span className="w-1 h-1 rounded-full mt-2 flex-shrink-0" style={{ background: COLORS.green }} />
                    {b}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {data.consignesSecurite && (
            <div className="mt-6">
              <h3 className="f-display text-base mb-2" style={{ color: COLORS.ink }}>Consignes de sécurité</h3>
              <ul className="space-y-1">
                {data.consignesSecurite.map((s, i) => (
                  <li key={i} className="flex items-start gap-2 f-body text-sm" style={{ color: COLORS.ink, opacity: 0.85 }}>
                    <span className="w-1 h-1 rounded-full mt-2 flex-shrink-0" style={{ background: COLORS.amberDark }} />
                    {s}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {data.enCasDeDoute && (
            <div className="mt-6 pt-4 border-t" style={{ borderColor: COLORS.line }}>
              <h3 className="f-display text-base mb-2" style={{ color: COLORS.ink }}>En cas de doute</h3>
              <p className="f-body text-sm" style={{ color: COLORS.ink, opacity: 0.85 }}>{data.enCasDeDoute}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Étoiles de notation (avis clients)
--------------------------------------------------------- */
function StarRating({ note, avis, size = 14 }) {
  return (
    <div className="flex items-center gap-1.5 mt-1">
      <div className="flex" style={{ gap: 1 }}>
        {[1, 2, 3, 4, 5].map((i) => (
          <Star
            key={i}
            size={size}
            color={COLORS.amberDark}
            fill={i <= Math.round(note) ? COLORS.amberDark : "none"}
          />
        ))}
      </div>
      <span className="f-mono text-xs" style={{ color: COLORS.ink, opacity: 0.65 }}>
        {note.toFixed(1)}/5 · {avis} avis
      </span>
    </div>
  );
}

function CompactBundle({ label, composition, sumPrice, prix, cartItem, addToCart, image, linkedProducts, onOpenDetails, modeEmploiKey, onOpenModeEmploi, note, avis, passages }) {
  return (
    <div className="flex flex-col justify-between border p-6" style={{ borderColor: COLORS.ink, background: COLORS.paper }}>
      <div>
        {image && (
          <div className="w-full h-36 mb-4 flex items-center justify-center overflow-hidden" style={{ background: COLORS.paperDim, border: `1px solid ${COLORS.line}` }}>
            <img src={image} alt={label} className="max-h-full max-w-full object-contain" />
          </div>
        )}
        <p className="f-mono text-xs tracking-wider uppercase" style={{ color: COLORS.amberDark }}>{label}</p>
        {note && <StarRating note={note} avis={avis} />}
        <ul className="mt-3 space-y-2">
          {composition.map((item) => {
            const kw = linkedProducts && Object.keys(linkedProducts).find((k) => item.includes(k));
            const linked = kw && findProductById(linkedProducts[kw]);
            return (
              <li key={item} className="flex items-start gap-2 f-mono text-xs" style={{ color: COLORS.ink }}>
                <span className="w-1 h-1 rounded-full mt-1.5 flex-shrink-0" style={{ background: COLORS.green }} />
                {linked ? (
                  <button onClick={() => onOpenDetails(linked)} className="text-left hover:underline">{item}</button>
                ) : (
                  item
                )}
              </li>
            );
          })}
        </ul>
        {modeEmploiKey && (
          <button
            onClick={() => onOpenModeEmploi(modeEmploiKey)}
            className="mt-4 f-mono text-xs underline hover:opacity-70"
            style={{ color: COLORS.amberDark }}
          >
            📋 Voir le mode d'emploi
          </button>
        )}
      </div>
      <div className="mt-6">
        {Math.round(prix * 100) < Math.round(sumPrice * 100) ? (
          <div className="flex items-baseline gap-2">
            <span className="f-display text-2xl" style={{ color: COLORS.ink, opacity: 0.4, textDecoration: "line-through" }}>{eur(sumPrice)}</span>
            <span className="f-display text-2xl" style={{ color: "#C0392B" }}>{eur(prix)}</span>
          </div>
        ) : (
          <p className="f-display text-2xl" style={{ color: COLORS.ink }}>{eur(prix)}</p>
        )}
        {passages && (
          <p className="f-mono text-xs italic mt-1" style={{ color: COLORS.ink, opacity: 0.6 }}>
            soit {eur(prix / passages)} par passage ({passages} passages)
          </p>
        )}
        <button onClick={() => addToCart(cartItem, 1)} className="w-full mt-4 f-body font-semibold text-sm py-2.5 transition-opacity hover:opacity-85" style={{ background: COLORS.ink, color: COLORS.paper }}>
          Ajouter
        </button>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   FAQ — question/réponse accordéon
--------------------------------------------------------- */
function FaqItem({ question, children }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="border-b" style={{ borderColor: COLORS.line }}>
      <button
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between text-left py-4 hover:opacity-80"
        style={{ color: COLORS.ink }}
      >
        <span className="f-body font-semibold text-sm sm:text-base pr-4">{question}</span>
        {open ? <Minus size={18} color={COLORS.amberDark} /> : <Plus size={18} color={COLORS.amberDark} />}
      </button>
      {open && (
        <p className="f-body text-sm pb-4 pr-6" style={{ color: COLORS.ink, opacity: 0.8 }}>
          {children}
        </p>
      )}
    </div>
  );
}

